{
  "name": "@bloom/api",
  "version": "0.0.0",
  "private": true,
  "description": "Bloom HttpApi contract (effect/http-api). Shared by the server, the web client, and OpenAPI emission.",
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./*": "./src/*.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "test": "bun test --pass-with-no-tests",
    "openapi": "bun run scripts/emit-openapi.ts"
  },
  "dependencies": {
    "@bloom/domain": "workspace:*",
    "effect": "4.0.0"
  }
}
import { HttpApi, OpenApi } from "effect/http-api";
import { HealthGroup } from "./groups/health.ts";
import { MeGroup } from "./groups/me.ts";
import { MessagesGroup } from "./groups/messages.ts";
import { TasksGroup } from "./groups/tasks.ts";
import { ThreadsGroup } from "./groups/threads.ts";

/**
 * The Bloom HTTP API: single source of truth for server handlers
 * (`HttpApiBuilder`), the web client (`HttpApiClient`) and `openapi.json`.
 *
 * Every route lives under `/api` (ADR 0004). `/api/auth/*` belongs to Better
 * Auth and is deliberately not part of this contract.
 */
export class BloomApi extends HttpApi.make("bloom")
  .add(HealthGroup, MeGroup, ThreadsGroup, MessagesGroup, TasksGroup)
  .prefix("/api")
  .annotateMerge(
    OpenApi.annotations({
      title: "Bloom API",
      version: "0.1.0",
      description:
        "HTTP contract of the Bloom personal agent. Authenticated routes rely on the Better Auth session cookie; chat replies stream as Server-Sent Events.",
    }),
  ) {}
import { UserId } from "@bloom/domain";
import { Context, Schema } from "effect";
import { HttpApiMiddleware } from "effect/http-api";

/** The authenticated owner as the API sees them; the wire shape of `GET /api/me`. */
export const AuthUser = Schema.Struct({
  id: UserId,
  email: Schema.String,
  name: Schema.String,
});
export type AuthUser = typeof AuthUser.Type;

/** Request-scoped service carrying the authenticated user; provided by `Authorization`. */
export class CurrentUser extends Context.Service<CurrentUser, AuthUser>()(
  "bloom/api/CurrentUser",
) {}

/** No valid session on the request. Encoded as HTTP 401. */
export class Unauthorized extends Schema.TaggedError<Unauthorized>()(
  "Unauthorized",
  { message: Schema.String },
  { httpApiStatus: 401 },
) {}

/**
 * Authorization middleware for every non-public endpoint.
 *
 * It declares no security scheme and is not `requiredForClient`: the browser
 * sends the Better Auth session cookie automatically and the server
 * implementation (in `apps/server`) reads the request headers itself. This
 * package only defines the contract; the implementation provides
 * `CurrentUser` to the wrapped handler or fails with `Unauthorized`.
 */
export class Authorization extends HttpApiMiddleware.Service<
  Authorization,
  { provides: CurrentUser }
>()("bloom/api/Authorization", { error: Unauthorized }) {}
import { Context, type Effect, Layer } from "effect";
import { FetchHttpClient, type HttpClient } from "effect/http";
import { HttpApiClient } from "effect/http-api";
import { BloomApi } from "./api.ts";

/** Options for the derived client. */
export interface BloomClientOptions {
  /**
   * Origin to prepend to every request, e.g. `http://localhost:3000`.
   * Omit it in the browser: paths already start with `/api` and resolve
   * against `location.origin` (ADR 0004, single origin).
   */
  readonly baseUrl?: string | URL | undefined;
}

/** The typed client shape derived from `BloomApi`. SSE endpoints return a `Stream`. */
export type BloomClientShape = HttpApiClient.ForApi<typeof BloomApi>;

/**
 * Builds the typed client from the API definition. Requires an `HttpClient`
 * (e.g. `FetchHttpClient.layer`); use `BloomClient.layer` for the ready-made
 * service.
 */
export const makeBloomClient = (
  options?: BloomClientOptions,
): Effect.Effect<BloomClientShape, never, HttpClient.HttpClient> =>
  HttpApiClient.make(BloomApi, { baseUrl: options?.baseUrl });

/**
 * The Bloom API client as a service, so the web app can `yield* BloomClient`.
 * `BloomClient.layer()` provides `FetchHttpClient`; the browser attaches the
 * session cookie itself, so no client middleware is required.
 */
export class BloomClient extends Context.Service<BloomClient, BloomClientShape>()(
  "bloom/api/BloomClient",
) {
  static readonly layer = (baseUrl?: string | URL): Layer.Layer<BloomClient> =>
    Layer.effect(BloomClient, makeBloomClient({ baseUrl })).pipe(
      Layer.provide(FetchHttpClient.layer),
    );
}
import { TaskNotFound, ThreadNotFound } from "@bloom/domain";
import { HttpApiSchema } from "effect/http-api";

/** `TaskNotFound` as an HTTP 404 response; the domain error class is used directly. */
export const TaskNotFound404 = TaskNotFound.pipe(HttpApiSchema.status(404));

/** `ThreadNotFound` as an HTTP 404 response; the domain error class is used directly. */
export const ThreadNotFound404 = ThreadNotFound.pipe(HttpApiSchema.status(404));
import { Schema } from "effect";
import { HttpApiEndpoint, HttpApiGroup, OpenApi } from "effect/http-api";

/** Liveness response. `time` is a `DateTime.Utc` in TypeScript and an ISO string on the wire. */
export const HealthStatus = Schema.Struct({
  status: Schema.Literal("ok"),
  service: Schema.Literal("bloom-server"),
  time: Schema.DateTimeUtcFromString,
});
export type HealthStatus = typeof HealthStatus.Type;

/** Public group (no `Authorization`): `GET /api/health`. */
export class HealthGroup extends HttpApiGroup.make("health")
  .add(
    HttpApiEndpoint.get("check", "/health", { success: HealthStatus }).annotateMerge(
      OpenApi.annotations({
        summary: "Liveness check",
        description: "Reports that the server is up and returns its current time.",
      }),
    ),
  )
  .annotateMerge(
    OpenApi.annotations({
      title: "Health",
      description: "Unauthenticated liveness endpoint.",
    }),
  ) {}
import { HttpApiEndpoint, HttpApiGroup, OpenApi } from "effect/http-api";
import { Authorization, AuthUser } from "../auth.ts";

/** `GET /api/me`: the authenticated owner. */
export class MeGroup extends HttpApiGroup.make("me")
  .add(
    HttpApiEndpoint.get("get", "/me", { success: AuthUser }).annotateMerge(
      OpenApi.annotations({
        summary: "Current user",
        description: "Returns the user the session cookie belongs to.",
      }),
    ),
  )
  .middleware(Authorization)
  .annotateMerge(
    OpenApi.annotations({
      title: "Me",
      description: "Identity of the signed-in owner.",
    }),
  ) {}
import { ChatStreamEvent, ThreadId } from "@bloom/domain";
import { Schema } from "effect";
import { HttpApiEndpoint, HttpApiGroup, HttpApiSchema, OpenApi } from "effect/http-api";
import { Authorization } from "../auth.ts";
import { ThreadNotFound404 } from "./errors.ts";

/** Body of `POST /api/threads/:id/messages`: the user's turn as plain text. */
export const SendMessage = Schema.Struct({ text: Schema.NonEmptyString });
export type SendMessage = typeof SendMessage.Type;

/**
 * Server-Sent Events stream of `ChatStreamEvent`s. Each SSE `data:` line is one
 * JSON-encoded event; the derived client exposes it as `Stream<ChatStreamEvent>`.
 */
export const ChatStream = HttpApiSchema.StreamSse({ data: ChatStreamEvent });

/** Sending a message to a thread and streaming the agent's reply. Requires `Authorization`. */
export class MessagesGroup extends HttpApiGroup.make("messages")
  .add(
    HttpApiEndpoint.post("send", "/threads/:id/messages", {
      params: { id: ThreadId },
      payload: SendMessage,
      success: ChatStream,
      error: ThreadNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Send a message and stream the reply",
        description:
          "Appends the user message to the thread, runs the agent, and streams `ChatStreamEvent`s as Server-Sent Events until `message_end` (or `error`).",
      }),
    ),
  )
  .middleware(Authorization)
  .annotateMerge(
    OpenApi.annotations({
      title: "Messages",
      description: "Chat turns. Replies stream as text/event-stream.",
    }),
  ) {}
import { Task, TaskId, TaskStatus } from "@bloom/domain";
import { Schema } from "effect";
import { HttpApiEndpoint, HttpApiGroup, OpenApi } from "effect/http-api";
import { Authorization } from "../auth.ts";
import { TaskNotFound404 } from "./errors.ts";

/** Query for `GET /api/tasks`: optional status filter (`?status=inbox&status=next`). */
export const TaskListQuery = {
  status: Schema.optional(Schema.Array(TaskStatus)),
};

/**
 * Payload for `POST /api/tasks`: the encoded side of `Task.jsonCreate`, so
 * every key except `title` is optional for the TypeScript client as well as
 * on the wire. Handlers turn it into a `TaskCreate` with
 * `decodePayload(Task.jsonCreate)`, which applies the defaults.
 */
export const TaskCreateInput = Schema.toEncoded(Task.jsonCreate);
export type TaskCreateInput = typeof TaskCreateInput.Type;

/** Task CRUD. All endpoints require `Authorization`; mutations go through `TaskService`. */
export class TasksGroup extends HttpApiGroup.make("tasks")
  .add(
    HttpApiEndpoint.get("list", "/", {
      query: TaskListQuery,
      success: Schema.Array(Task.json),
    }).annotateMerge(
      OpenApi.annotations({
        summary: "List tasks",
        description: "Tasks in creation order, optionally filtered by one or more statuses.",
      }),
    ),
    HttpApiEndpoint.post("create", "/", {
      payload: TaskCreateInput,
      success: Task.json,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Create a task",
        description:
          "Creates a task. Omitted fields take their defaults (`status: inbox`, nullable fields `null`).",
      }),
    ),
    HttpApiEndpoint.get("get", "/:id", {
      params: { id: TaskId },
      success: Task.json,
      error: TaskNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Get a task",
        description: "One task by id.",
      }),
    ),
    HttpApiEndpoint.patch("update", "/:id", {
      params: { id: TaskId },
      payload: Task.jsonUpdate,
      success: Task.json,
      error: TaskNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Patch a task",
        description:
          "Partial update: only the keys present are changed. `completedAt` is managed by the server from `status`.",
      }),
    ),
    HttpApiEndpoint.post("complete", "/:id/complete", {
      params: { id: TaskId },
      success: Task.json,
      error: TaskNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Complete a task",
        description: "Sets `status` to `done` and stamps `completedAt`.",
      }),
    ),
    HttpApiEndpoint.delete("remove", "/:id", {
      params: { id: TaskId },
      error: TaskNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Delete a task",
        description: "Removes the task. Responds 204 with no body.",
      }),
    ),
  )
  .middleware(Authorization)
  .prefix("/tasks")
  .annotateMerge(
    OpenApi.annotations({
      title: "Tasks",
      description: "Things to do once: the central domain object.",
    }),
  ) {}
import { Message, Thread, ThreadId } from "@bloom/domain";
import { Schema, Struct } from "effect";
import { HttpApiEndpoint, HttpApiGroup, OpenApi } from "effect/http-api";
import { Authorization } from "../auth.ts";
import { ThreadNotFound404 } from "./errors.ts";

/** Query for `GET /api/threads/:id/messages`: return only the most recent `limit` messages. */
export const MessageListQuery = {
  limit: Schema.optional(Schema.Int.check(Schema.isGreaterThanOrEqualTo(1))),
};

/** Thread kinds a client may create. The single `main` thread is obtained via `GET /api/threads/main`. */
export const CreatableThreadKind = Schema.Literals(["side", "quest"]);
export type CreatableThreadKind = typeof CreatableThreadKind.Type;

/**
 * Payload for `POST /api/threads`: the encoded side of `Thread.jsonCreate`
 * (every key but `kind` optional) with `kind` narrowed to `side | quest`, so
 * no client can mint a second `main` thread. Handlers turn it into a
 * `ThreadCreate` with `decodePayload(Thread.jsonCreate)`.
 */
export const ThreadCreateInput = Schema.toEncoded(
  Thread.jsonCreate.mapFields(Struct.assign({ kind: CreatableThreadKind })),
);
export type ThreadCreateInput = typeof ThreadCreateInput.Type;

/** Conversation threads and their message history. All endpoints require `Authorization`. */
export class ThreadsGroup extends HttpApiGroup.make("threads")
  .add(
    HttpApiEndpoint.get("list", "/", { success: Schema.Array(Thread.json) }).annotateMerge(
      OpenApi.annotations({
        summary: "List threads",
        description: "All threads in creation order.",
      }),
    ),
    HttpApiEndpoint.post("create", "/", {
      payload: ThreadCreateInput,
      success: Thread.json,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Create a side thread or quest",
        description:
          "Creates a `side` or `quest` thread; the `main` thread cannot be created here (see `GET /api/threads/main`). When `contextScope` is omitted, side threads get `minimal` and quests get `full`.",
      }),
    ),
    HttpApiEndpoint.get("main", "/main", { success: Thread.json }).annotateMerge(
      OpenApi.annotations({
        summary: "Get the main thread",
        description:
          "The single ongoing conversation. Created on first call, so this is idempotent and never 404s.",
      }),
    ),
    HttpApiEndpoint.get("get", "/:id", {
      params: { id: ThreadId },
      success: Thread.json,
      error: ThreadNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "Get a thread",
        description: "One thread by id.",
      }),
    ),
    HttpApiEndpoint.get("messages", "/:id/messages", {
      params: { id: ThreadId },
      query: MessageListQuery,
      success: Schema.Array(Message.json),
      error: ThreadNotFound404,
    }).annotateMerge(
      OpenApi.annotations({
        summary: "List messages in a thread",
        description:
          "Messages in chronological order. With `limit`, only the most recent `limit` messages are returned, still oldest first.",
      }),
    ),
  )
  .middleware(Authorization)
  .prefix("/threads")
  .annotateMerge(
    OpenApi.annotations({
      title: "Threads",
      description: "Conversation threads: the main thread, side threads, and quests.",
    }),
  ) {}
/**
 * @bloom/api: the HttpApi contract shared by the server (handlers), the web
 * app (derived client) and the OpenAPI document. No implementation lives here.
 */
export * from "./api.ts";
export * from "./auth.ts";
export * from "./client.ts";
export * from "./groups/errors.ts";
export * from "./groups/health.ts";
export * from "./groups/me.ts";
export * from "./groups/messages.ts";
export * from "./groups/tasks.ts";
export * from "./groups/threads.ts";
export * from "./openapi.ts";
export * from "./payload.ts";
import { OpenApi } from "effect/http-api";
import { BloomApi } from "./api.ts";

/** The OpenAPI 3.1 document for `BloomApi` (a fresh copy on each call). */
export const openApiSpec = (): OpenApi.OpenAPISpec => OpenApi.fromApi(BloomApi);

/** `openApiSpec()` as pretty-printed JSON with a trailing newline, the content of `packages/api/openapi.json`. */
export const renderOpenApiJson = (): string => `${JSON.stringify(openApiSpec(), null, 2)}\n`;
import { Effect, Schema } from "effect";
import { HttpApiError } from "effect/http-api";

/**
 * Decodes an endpoint payload declared with `Schema.toEncoded(X)` into `X`'s
 * decoded type (defaults applied, timestamps parsed).
 *
 * Create endpoints declare their payload as the encoded side of the domain
 * `jsonCreate` variant so the derived TypeScript client can send a minimal
 * body (`{ title }`) instead of every key. The handler then calls
 * `decodePayload(Task.jsonCreate)(payload)` before handing the result to the
 * domain service.
 *
 * The encoded side already enforces the shape, so a decode failure can only
 * come from a value-level check the encoded side cannot express (an ISO
 * timestamp that does not parse, for example). Such a failure becomes
 * `HttpApiError.HttpApiSchemaError` with kind `Payload`, which is exactly what
 * `HttpApiBuilder` raises for its own payload decoding: it renders as an
 * empty `400 Bad Request`.
 */
export const decodePayload = <Source extends Schema.Top>(schema: Source) => {
  const decode = Schema.decodeUnknownEffect(schema);
  return (
    input: Source["Encoded"],
  ): Effect.Effect<Source["Type"], never, Source["DecodingServices"]> =>
    decode(input).pipe(
      Effect.catch((cause) =>
        Effect.die(new HttpApiError.HttpApiSchemaError({ kind: "Payload", cause })),
      ),
    );
};
/**
 * Writes `packages/api/openapi.json` from the `BloomApi` definition.
 *
 * Run from the repo root with `bun run openapi`. An optional first argument
 * overrides the output path (used by the tests).
 */
import { Effect, Schema } from "effect";
import { renderOpenApiJson } from "../src/openapi.ts";

class OpenApiWriteError extends Schema.TaggedError<OpenApiWriteError>()("OpenApiWriteError", {
  path: Schema.String,
  cause: Schema.Defect(),
}) {}

const defaultOutput = new URL("../openapi.json", import.meta.url);
const outputArg = process.argv[2];
const output: string | URL = outputArg === undefined ? defaultOutput : outputArg;
const outputPath = typeof output === "string" ? output : output.pathname;

const program = Effect.gen(function* () {
  const json = renderOpenApiJson();
  yield* Effect.tryPromise({
    try: () => Bun.write(output, json),
    catch: (cause) => new OpenApiWriteError({ path: outputPath, cause }),
  });
  yield* Effect.log(`wrote ${outputPath}`);
}).pipe(Effect.withSpan("emit-openapi"));

await Effect.runPromise(program);

