import { Schema } from "effect";
import { Model } from "effect/schema";
import { Immutable, Nullable, WithDefault } from "./fields.ts";
import { CaptureId } from "./ids.ts";

/** Modality of a raw capture. */
export const CaptureKind = Schema.Literals(["text", "voice", "share", "image"]);
export type CaptureKind = typeof CaptureKind.Type;

/** Triage state of a capture. */
export const CaptureStatus = Schema.Literals(["new", "routed", "dismissed"]);
export type CaptureStatus = typeof CaptureStatus.Type;

/**
 * Raw input before triage (quick text, voice memo, share-sheet link, photo).
 * `kind` and `payload` are write-once; triage patches `transcript`, `status`, `routedTo`.
 */
export class Capture extends Model.Class<Capture>("Capture")({
  id: Model.UuidV7Insert(CaptureId),
  kind: Immutable(CaptureKind),
  payload: Immutable(Schema.Json),
  transcript: Nullable(Schema.String),
  status: WithDefault(CaptureStatus, "new"),
  /** Where triage sent it, e.g. "task:<id>" or "reader". */
  routedTo: Nullable(Schema.String),
  createdAt: Model.DateTimeInsertFromDate,
  updatedAt: Model.DateTimeUpdateFromDate,
}) {}
import { Schema } from "effect";
import { Model } from "effect/schema";
import { Immutable, ImmutableTimestamp, Nullable } from "./fields.ts";
import { EventId } from "./ids.ts";

/**
 * Anything that happened that Bloom might care about: webhooks, pollers, client
 * uploads, internal timers. `dedupeKey` is unique in the DB so ingestion is idempotent.
 * Events are append-only: every field is write-once.
 */
export class Event extends Model.Class<Event>("Event")({
  id: Model.UuidV7Insert(EventId),
  /** Producer of the event, e.g. "system", "domain", "gmail". */
  source: Immutable(Schema.String),
  /** Producer-specific event type, e.g. "task.completed", "calendar.event_moved". */
  type: Immutable(Schema.String),
  occurredAt: ImmutableTimestamp,
  payload: Immutable(Schema.Json),
  dedupeKey: Nullable(Schema.String),
  createdAt: Model.DateTimeInsertFromDate,
}) {}

/** Input for `EventSink.ingest`; `dedupeKey` may be omitted. */
export const EventIngest = Schema.Struct({
  source: Schema.String,
  type: Schema.String,
  occurredAt: Schema.DateTimeUtcFromString,
  payload: Schema.Json,
  dedupeKey: Schema.optionalKey(Schema.NullOr(Schema.String)),
});
export type EventIngest = typeof EventIngest.Type;
import { Schema } from "effect";
import { MessageId, ThreadId } from "./ids.ts";
import { Message } from "./message.ts";
import { UiComponent } from "./ui-component.ts";

/** A new assistant message has started. */
export const MessageStartEvent = Schema.Struct({
  type: Schema.Literal("message_start"),
  messageId: MessageId,
  threadId: ThreadId,
});

/** Incremental text appended to the current message. */
export const TextDeltaEvent = Schema.Struct({
  type: Schema.Literal("text_delta"),
  messageId: MessageId,
  delta: Schema.String,
});

/** The model requested a tool call. */
export const ToolCallEvent = Schema.Struct({
  type: Schema.Literal("tool_call"),
  messageId: MessageId,
  toolCallId: Schema.String,
  name: Schema.String,
  args: Schema.Json,
});

/** A tool call finished; full result lives in the message parts. */
export const ToolResultEvent = Schema.Struct({
  type: Schema.Literal("tool_result"),
  messageId: MessageId,
  toolCallId: Schema.String,
  name: Schema.String,
  ok: Schema.Boolean,
});

/** A UI component was emitted into the current message. */
export const UiComponentEvent = Schema.Struct({
  type: Schema.Literal("ui_component"),
  messageId: MessageId,
  component: UiComponent,
});

/** Tasks changed during the run; clients should refetch. */
export const TasksChangedEvent = Schema.Struct({ type: Schema.Literal("tasks_changed") });

/** The message is complete; carries the final persisted message. */
export const MessageEndEvent = Schema.Struct({
  type: Schema.Literal("message_end"),
  message: Message.json,
});

/** The run failed; `message` is safe to show the user. */
export const StreamErrorEvent = Schema.Struct({
  type: Schema.Literal("error"),
  message: Schema.String,
});

/**
 * Server-to-web SSE event for a chat run. Discriminated on `type`;
 * use `ChatStreamEvent.match` / `.guards`.
 */
export const ChatStreamEvent = Schema.Union([
  MessageStartEvent,
  TextDeltaEvent,
  ToolCallEvent,
  ToolResultEvent,
  UiComponentEvent,
  TasksChangedEvent,
  MessageEndEvent,
  StreamErrorEvent,
]).pipe(Schema.toTaggedUnion("type"));
export type ChatStreamEvent = typeof ChatStreamEvent.Type;
import { Schema } from "effect";
import { Model } from "effect/schema";
import { Nullable, NullableTimestamp, Patchable, ServerTimestamp, WithDefault } from "./fields.ts";
import { TaskId } from "./ids.ts";

/** Lifecycle of a task; `inbox` until triaged. */
export const TaskStatus = Schema.Literals([
  "inbox",
  "next",
  "scheduled",
  "waiting",
  "done",
  "dropped",
]);
export type TaskStatus = typeof TaskStatus.Type;

/** Kind of energy a task needs, so Bloom can match tasks to how Gabby feels. */
export const EnergyKind = Schema.Literals(["focus", "admin", "physical", "social", "rest"]);
export type EnergyKind = typeof EnergyKind.Type;

/** Where a task came from. */
export const TaskSource = Schema.Literals(["user", "agent", "import", "integration"]);
export type TaskSource = typeof TaskSource.Type;

/** Effort in spoons, 1 (trivial) to 5 (a whole day's energy). */
export const Effort = Schema.Int.check(Schema.isBetween({ minimum: 1, maximum: 5 }));
export type Effort = typeof Effort.Type;

/**
 * A thing to do once. The central domain object; agents mutate it only through
 * `TaskService`. Variants: `Task`/`insert`/`update` for the DB, `json`/`jsonCreate`/`jsonUpdate` for the API.
 */
export class Task extends Model.Class<Task>("Task")({
  id: Model.UuidV7Insert(TaskId),
  title: Patchable(Schema.NonEmptyString),
  notes: Nullable(Schema.String),
  status: WithDefault(TaskStatus, "inbox"),
  due: NullableTimestamp,
  scheduledFor: NullableTimestamp,
  effort: Nullable(Effort),
  energyKind: Nullable(EnergyKind),
  area: Nullable(Schema.String),
  source: WithDefault(TaskSource, "user"),
  parentId: Nullable(TaskId),
  completedAt: ServerTimestamp,
  createdAt: Model.DateTimeInsertFromDate,
  updatedAt: Model.DateTimeUpdateFromDate,
}) {}

/** Client payload for creating a task (decoded; defaults applied). */
export type TaskCreate = typeof Task.jsonCreate.Type;
/** Client payload for patching a task; every key optional. */
export type TaskUpdate = typeof Task.jsonUpdate.Type;

