import { Schema } from "effect";
import { Model } from "effect/schema";
import { Immutable, Nullable, Patchable } from "./fields.ts";
import { MessageId, RunId, ThreadId } from "./ids.ts";
import { MessagePart } from "./message-part.ts";

/** Who authored a message turn. */
export const MessageRole = Schema.Literals(["user", "assistant", "system", "tool"]);
export type MessageRole = typeof MessageRole.Type;

/** Concatenates the text of all `text` parts, in order, separated by newlines. */
export const messageText = (message: { readonly parts: ReadonlyArray<MessagePart> }): string =>
  message.parts
    .filter(MessagePart.guards.text)
    .map((part) => part.text)
    .join("\n");

/**
 * One turn in a thread. `parts` is stored as jsonb (pg decodes it to parsed JSON,
 * so the same `Schema.Array(MessagePart)` works in every variant). Immutable except `parts`.
 */
export class Message extends Model.Class<Message>("Message")({
  id: Model.UuidV7Insert(MessageId),
  threadId: Immutable(ThreadId),
  role: Immutable(MessageRole),
  parts: Patchable(Schema.Array(MessagePart)),
  runId: Nullable(RunId),
  createdAt: Model.DateTimeInsertFromDate,
}) {
  /** Text content of a message: all `text` parts joined with newlines. */
  static text(message: { readonly parts: ReadonlyArray<MessagePart> }): string {
    return messageText(message);
  }
}

/** Input for `MessageService.append`; `runId` may be omitted. */
export const MessageAppend = Schema.Struct({
  threadId: ThreadId,
  role: MessageRole,
  parts: Schema.Array(MessagePart),
  runId: Schema.optionalKey(Schema.NullOr(RunId)),
});
export type MessageAppend = typeof MessageAppend.Type;
import { Schema } from "effect";
import { UiComponent } from "./ui-component.ts";

/** Plain text. */
export const TextPart = Schema.Struct({ type: Schema.Literal("text"), text: Schema.String });
export type TextPart = typeof TextPart.Type;

/** An image by URL with optional alt text. */
export const ImagePart = Schema.Struct({
  type: Schema.Literal("image"),
  url: Schema.String,
  alt: Schema.optionalKey(Schema.String),
});
export type ImagePart = typeof ImagePart.Type;

/** A tool invocation requested by the model. */
export const ToolCallPart = Schema.Struct({
  type: Schema.Literal("tool_call"),
  id: Schema.String,
  name: Schema.String,
  args: Schema.Json,
});
export type ToolCallPart = typeof ToolCallPart.Type;

/** The result of a tool invocation, matched by `toolCallId`. */
export const ToolResultPart = Schema.Struct({
  type: Schema.Literal("tool_result"),
  toolCallId: Schema.String,
  name: Schema.String,
  ok: Schema.Boolean,
  result: Schema.Json,
});
export type ToolResultPart = typeof ToolResultPart.Type;

/** A generative UI component embedded in the message. */
export const UiComponentPart = Schema.Struct({
  type: Schema.Literal("ui_component"),
  component: UiComponent,
});
export type UiComponentPart = typeof UiComponentPart.Type;

/**
 * One piece of a message. Stored as jsonb; discriminated on `type`.
 * Use `MessagePart.match` for exhaustive handling and `MessagePart.guards.text` etc. for narrowing.
 */
export const MessagePart = Schema.Union([
  TextPart,
  ImagePart,
  ToolCallPart,
  ToolResultPart,
  UiComponentPart,
]).pipe(Schema.toTaggedUnion("type"));
export type MessagePart = typeof MessagePart.Type;
import { Schema } from "effect";
import { TaskId } from "./ids.ts";
import { TaskStatus } from "./task.ts";

/** One selectable choice in an `OptionPicker`. */
export const UiOption = Schema.Struct({ id: Schema.String, label: Schema.String });
export type UiOption = typeof UiOption.Type;

/** Asks the user to pick one of a few options. */
export const OptionPicker = Schema.Struct({
  kind: Schema.Literal("option_picker"),
