import { Context, Effect, Layer, Ref } from "effect";
import { MessageNotFound } from "../errors.ts";
import type { MessageId, ThreadId } from "../ids.ts";
import type { MessagePart } from "../message-part.ts";
import { Message, type MessageAppend } from "../message.ts";

/** Options for `MessageService.list`. */
export interface MessageListOptions {
  /** Return only the most recent `limit` messages (still in chronological order). */
  readonly limit?: number;
}

/**
 * Operations on messages within threads.
 *
 * Ordering contract: `list` returns messages in append order. Implementations
 * must order by `(created_at, id)` or by a sequence column, never by `id`
 * alone: UUIDv7 ids share a millisecond prefix and the remaining bits are random.
 */
export interface MessageServiceShape {
  readonly list: (
    threadId: ThreadId,
    options?: MessageListOptions,
  ) => Effect.Effect<ReadonlyArray<Message>>;
  readonly append: (input: MessageAppend) => Effect.Effect<Message>;
  /** Replaces the parts of an existing message (used while a run streams). */
  readonly replaceParts: (
    id: MessageId,
    parts: ReadonlyArray<MessagePart>,
  ) => Effect.Effect<Message, MessageNotFound>;
}

/** Message domain service with a Ref-backed `layerMemory` for tests. */
export class MessageService extends Context.Service<MessageService, MessageServiceShape>()(
  "bloom/domain/MessageService",
) {
  static readonly layerMemory = Layer.effect(
    MessageService,
    Effect.gen(function* () {
      // Map iteration order is insertion order, and re-setting an existing key
      // keeps its position, so the store itself is the append-order index.
      const store = yield* Ref.make(new Map<MessageId, Message>());

      const put = (message: Message) =>
        Ref.update(store, (messages) => new Map(messages).set(message.id, message));

      const list = Effect.fn("MessageService.list")(function* (
        threadId: ThreadId,
        options?: MessageListOptions,
      ) {
        const all = Array.from((yield* Ref.get(store)).values()).filter(
          (message) => message.threadId === threadId,
        );
        const limit = options?.limit;
        return limit === undefined ? all : all.slice(Math.max(0, all.length - limit));
      });

      const append = Effect.fn("MessageService.append")(function* (input: MessageAppend) {
        const message = new Message(
          yield* Message.insert
            .makeEffect({
              threadId: input.threadId,
              role: input.role,
              parts: input.parts,
              runId: input.runId ?? null,
            })
            .pipe(Effect.orDie),
        );
        yield* put(message);
        return message;
      });

      const replaceParts = Effect.fn("MessageService.replaceParts")(function* (
        id: MessageId,
        parts: ReadonlyArray<MessagePart>,
      ) {
        const existing = (yield* Ref.get(store)).get(id);
        if (existing === undefined) {
          return yield* new MessageNotFound({ id });
        }
        // oxlint-disable-next-line typescript/no-misused-spread -- fields are copied; the class constructor re-validates
        const next = new Message({ ...existing, parts });
        yield* put(next);
        return next;
      });

      return MessageService.of({ list, append, replaceParts });
    }),
  );
}
import { Context, DateTime, Effect, Layer, Ref } from "effect";
import type { Actor } from "../actor.ts";
import { TaskNotFound } from "../errors.ts";
import type { TaskId } from "../ids.ts";
import { Task, type TaskCreate, type TaskStatus, type TaskUpdate } from "../task.ts";

/** Optional filter for `TaskService.list`. */
export interface TaskListFilter {
  readonly status?: ReadonlyArray<TaskStatus>;
}

/**
 * Operations on tasks. The only way agents and the API may mutate tasks.
 *
 * Ordering contract: `list` returns tasks in creation order. Implementations
 * must order by `(created_at, id)` or a sequence column, never by `id` alone
 * (UUIDv7 ids created in the same millisecond have no defined order).
 * `completedAt` is owned by the service: set when status becomes `done`,
 * cleared when it leaves `done`.
 */
export interface TaskServiceShape {
  readonly create: (input: TaskCreate, actor: Actor) => Effect.Effect<Task>;
  readonly list: (filter?: TaskListFilter) => Effect.Effect<ReadonlyArray<Task>>;
  readonly get: (id: TaskId) => Effect.Effect<Task, TaskNotFound>;
  readonly update: (
    id: TaskId,
    patch: TaskUpdate,
    actor: Actor,
  ) => Effect.Effect<Task, TaskNotFound>;
  readonly complete: (id: TaskId, actor: Actor) => Effect.Effect<Task, TaskNotFound>;
  readonly remove: (id: TaskId, actor: Actor) => Effect.Effect<void, TaskNotFound>;
}

/**
 * Task domain service. `layerMemory` is a Ref-backed implementation for tests
 * and the agent harness; the DB-backed layer lives in `@bloom/db`.
 */
export class TaskService extends Context.Service<TaskService, TaskServiceShape>()(
  "bloom/domain/TaskService",
) {
  static readonly layerMemory = Layer.effect(
    TaskService,
    Effect.gen(function* () {
      // Map iteration order is insertion order, and re-setting an existing key
      // keeps its position, so the store itself is the creation-order index.
      const store = yield* Ref.make(new Map<TaskId, Task>());

      const lookup = Effect.fnUntraced(function* (id: TaskId) {
        const tasks = yield* Ref.get(store);
        const task = tasks.get(id);
        if (task === undefined) {
          return yield* new TaskNotFound({ id });
        }
        return task;
      });

      const put = (task: Task) => Ref.update(store, (tasks) => new Map(tasks).set(task.id, task));

      const create = Effect.fn("TaskService.create")(function* (input: TaskCreate, _actor: Actor) {
        const now = yield* DateTime.now;
        const task = yield* Task.insert
          .makeEffect({ ...input, completedAt: input.status === "done" ? now : null })
          .pipe(Effect.orDie);
        const stored = new Task(task);
        yield* put(stored);
        return stored;
      });

      const list = Effect.fn("TaskService.list")(function* (filter?: TaskListFilter) {
        const tasks = Array.from((yield* Ref.get(store)).values());
        const statuses = filter?.status;
        return statuses === undefined
          ? tasks
          : tasks.filter((task) => statuses.includes(task.status));
      });

      const get = Effect.fn("TaskService.get")(function* (id: TaskId) {
        return yield* lookup(id);
      });

      const update = Effect.fn("TaskService.update")(function* (
        id: TaskId,
        patch: TaskUpdate,
        _actor: Actor,
      ) {
        const existing = yield* lookup(id);
        const now = yield* DateTime.now;
        // oxlint-disable-next-line typescript/no-misused-spread -- fields are copied; the class constructor re-validates
        const merged = { ...existing, ...patch, updatedAt: now };
        const completedAt =
          merged.status === "done"
            ? (existing.completedAt ?? now)
            : existing.status === "done"
              ? null
              : existing.completedAt;
        const next = new Task({ ...merged, completedAt });
        yield* put(next);
        return next;
      });

      const complete = Effect.fn("TaskService.complete")(function* (id: TaskId, actor: Actor) {
        return yield* update(id, { status: "done" }, actor);
      });

      const remove = Effect.fn("TaskService.remove")(function* (id: TaskId, _actor: Actor) {
        yield* lookup(id);
        yield* Ref.update(store, (tasks) => {
          const next = new Map(tasks);
          next.delete(id);
          return next;
        });
      });

      return TaskService.of({ create, list, get, update, complete, remove });
    }),
  );
}
import { Context, type DateTime, Effect, Layer, Ref } from "effect";
import { ThreadNotFound } from "../errors.ts";
import type { ThreadId } from "../ids.ts";
import { Thread, type ThreadCreate, defaultContextScope } from "../thread.ts";

/**
 * Operations on conversation threads.
 *
 * Ordering contract: `list` returns threads in creation order. Implementations
 * must order by `(created_at, id)` or a sequence column, never by `id` alone.
 * `create` applies `defaultContextScope(kind)` when the input omits `contextScope`;
 * `lastMessageAt` is owned by `touch`.
 */
export interface ThreadServiceShape {
  readonly list: Effect.Effect<ReadonlyArray<Thread>>;
  readonly create: (input: ThreadCreate) => Effect.Effect<Thread>;
  readonly get: (id: ThreadId) => Effect.Effect<Thread, ThreadNotFound>;
  /** Returns the single `main` thread, creating it on first use. */
  readonly ensureMain: Effect.Effect<Thread>;
  /** Records that a message landed in the thread at `at`. */
  readonly touch: (id: ThreadId, at: DateTime.Utc) => Effect.Effect<void, ThreadNotFound>;
}

/** Thread domain service with a Ref-backed `layerMemory` for tests. */
export class ThreadService extends Context.Service<ThreadService, ThreadServiceShape>()(
  "bloom/domain/ThreadService",
) {
  static readonly layerMemory = Layer.effect(
    ThreadService,
    Effect.gen(function* () {
      // Map iteration order is insertion order, and re-setting an existing key
      // keeps its position, so the store itself is the creation-order index.
      const store = yield* Ref.make(new Map<ThreadId, Thread>());

      const lookup = Effect.fnUntraced(function* (id: ThreadId) {
        const thread = (yield* Ref.get(store)).get(id);
        if (thread === undefined) {
          return yield* new ThreadNotFound({ id });
        }
        return thread;
      });

      const put = (thread: Thread) =>
        Ref.update(store, (threads) => new Map(threads).set(thread.id, thread));

      const list = Ref.get(store).pipe(
        Effect.map((threads) => Array.from(threads.values())),
        Effect.withSpan("ThreadService.list"),
      );

      const create = Effect.fn("ThreadService.create")(function* (input: ThreadCreate) {
        const thread = new Thread(
          yield* Thread.insert
            .makeEffect({
              ...input,
              contextScope: input.contextScope ?? defaultContextScope(input.kind),
            })
            .pipe(Effect.orDie),
        );
        yield* put(thread);
        return thread;
      });

      const get = Effect.fn("ThreadService.get")(function* (id: ThreadId) {
        return yield* lookup(id);
      });

      const ensureMain = Effect.gen(function* () {
        const existing = Array.from((yield* Ref.get(store)).values()).find(
          (thread) => thread.kind === "main",
        );
        if (existing !== undefined) {
          return existing;
        }
        return yield* create({
          kind: "main",
          parentThreadId: null,
          topic: null,
          status: "active",
        });
      }).pipe(Effect.withSpan("ThreadService.ensureMain"));

      const touch = Effect.fn("ThreadService.touch")(function* (id: ThreadId, at: DateTime.Utc) {
        const existing = yield* lookup(id);
        // oxlint-disable-next-line typescript/no-misused-spread -- fields are copied; the class constructor re-validates
        yield* put(new Thread({ ...existing, lastMessageAt: at, updatedAt: at }));
      });

      return ThreadService.of({ list, create, get, ensureMain, touch });
    }),
  );
}
