 * Single user, passkeys only. The first session is created from a magic link
 * issued by the CLI (`bun run auth:link`), never from a sign-up flow. See
 * docs/adrs/0003-auth-bootstrap-magic-link-then-passkeys.md.
 *
 * This module builds the Better Auth instance from explicit options so the
 * server can construct it inside an Effect Layer. It has no module-level
 * singleton; `better-auth.cli.ts` is the only place that instantiates it at
 * import time, and only for schema generation.
 */
import { passkey } from "@better-auth/passkey";
import { betterAuth } from "better-auth";
import { magicLink } from "better-auth/plugins";
import type { Pool } from "pg";

export interface AuthOptions {
  /**
   * Postgres pool. Better Auth owns the user/session/account/verification/passkey
   * tables. The caller owns the pool's lifecycle (the server releases it with
   * its Layer; the CLI config never connects).
   */
  readonly database: Pool;
  /** 32+ random bytes, base64. Used for signing cookies and hashing tokens. */
  readonly secret: string;
  /** The browser origin, e.g. http://localhost:5173. Cookies and passkeys bind to it. */
  readonly webOrigin: string;
  /** WebAuthn relying-party id, usually the hostname of `webOrigin`. */
  readonly rpId: string;
  readonly rpName: string;
  /** Called when a magic link is issued. Bloom prints it to the terminal instead of emailing it. */
  readonly onMagicLink: (link: { readonly email: string; readonly url: string }) => Promise<void>;
}

export const AUTH_BASE_PATH = "/api/auth";

/** Magic links stay valid for 15 minutes: long enough to copy from a terminal, short enough to not matter if leaked. */
export const MAGIC_LINK_EXPIRES_IN_SECONDS = 15 * 60;

export const createAuth = (options: AuthOptions) =>
  betterAuth({
    appName: "Bloom",
    database: options.database,
    secret: options.secret,
    baseURL: options.webOrigin,
    basePath: AUTH_BASE_PATH,
    trustedOrigins: [options.webOrigin],
    emailAndPassword: { enabled: false },
    databaseHooks: {
      user: {
        create: {
          // Bloom has exactly one user, created by `bun run db:seed`. Refuse
          // any runtime user creation regardless of which plugin asks.
          before: async () => false,
        },
      },
    },
    plugins: [
      magicLink({
        expiresIn: MAGIC_LINK_EXPIRES_IN_SECONDS,
        disableSignUp: true,
        sendMagicLink: async ({ email, url }) => options.onMagicLink({ email, url }),
      }),
      passkey({
        rpID: options.rpId,
        rpName: options.rpName,
        origin: options.webOrigin,
        authenticatorSelection: {
          residentKey: "required",
          userVerification: "preferred",
        },
      }),
    ],
  });

export type Auth = ReturnType<typeof createAuth>;
/**
 * Implementation of the `Authorization` middleware declared in `@bloom/api`:
 * resolves the Better Auth session cookie and provides `CurrentUser` to the
 * wrapped handler, or fails with `Unauthorized` (HTTP 401).
 */
import { Authorization, CurrentUser, Unauthorized } from "@bloom/api";
import { UserId } from "@bloom/domain";
import { Effect, Layer, Option, Schema } from "effect";
import { HttpServerRequest } from "effect/http";
import { Auth } from "./service.ts";

const decodeUserId = Schema.decodeSync(UserId);

/** What the client sees; deliberately free of detail. */
export const SIGN_IN_MESSAGE = "Please sign in.";

/**
 * Only the `cookie` header reaches Better Auth; nothing from it is logged. A
 * future bearer-token flow for iOS would forward `authorization` here too.
 */
export const sessionHeaders = (request: HttpServerRequest.HttpServerRequest): Headers => {
  const headers = new Headers();
  const cookie = request.headers["cookie"];
  if (cookie !== undefined) {
    headers.set("cookie", cookie);
  }
  return headers;
};

export const AuthorizationLive: Layer.Layer<Authorization, never, Auth> = Layer.effect(
  Authorization,
  Effect.gen(function* () {
    const auth = yield* Auth;
    return Authorization.of((httpEffect) =>
      Effect.gen(function* () {
        const request = yield* HttpServerRequest.HttpServerRequest;
        const session = yield* auth
          .getSession(sessionHeaders(request))
          .pipe(
            Effect.catchTag("AuthError", (error) =>
              Effect.logWarning("session lookup failed").pipe(
                Effect.annotateLogs({ "bloom.auth.operation": error.operation }),
                Effect.andThen(Effect.fail(new Unauthorized({ message: SIGN_IN_MESSAGE }))),
              ),
            ),
          );
        if (Option.isNone(session)) {
          return yield* new Unauthorized({ message: SIGN_IN_MESSAGE });
        }
        const { user } = session.value;
        yield* Effect.annotateCurrentSpan("bloom.user_id", user.id);
        return yield* Effect.provideService(httpEffect, CurrentUser, {
          id: decodeUserId(user.id),
          email: user.email,
          name: user.name,
        });
      }).pipe(Effect.withSpan("auth.session")),
    );
  }),
);
/**
 * `Auth`: the Better Auth instance as an Effect service. Built inside a Layer
 * from `ServerConfig`; the `pg` Pool it owns is released with the Layer.
 * Promise APIs are wrapped in `Effect.tryPromise` and bounded by timeouts.
 */
import { Context, Effect, Layer, Option, Redacted, Schema } from "effect";
import { Pool } from "pg";
import { ServerConfig } from "../config.ts";
import { createAuth } from "./auth.ts";

/** Better Auth threw or timed out. `cause` never carries cookies or tokens. */
export class AuthError extends Schema.TaggedError<AuthError>()("AuthError", {
  operation: Schema.Literals(["handle", "getSession", "requestMagicLink"]),
  cause: Schema.Defect(),
}) {}

/** The signed-in user as Better Auth stores it. */
export interface SessionUser {
  readonly id: string;
  readonly email: string;
  readonly name: string;
}

export interface AuthShape {
  /** Routes a Web `Request` under `/api/auth/*` to Better Auth. */
  readonly handle: (request: Request) => Effect.Effect<Response, AuthError>;
  /** Resolves the session cookie in `headers`; `None` when there is no valid session. */
  readonly getSession: (
    headers: Headers,
  ) => Effect.Effect<Option.Option<{ readonly user: SessionUser }>, AuthError>;
  /** Asks Better Auth to issue a magic link for `email`; the link is delivered through `onMagicLink`. */
  readonly requestMagicLink: (email: string) => Effect.Effect<void, AuthError>;
}

/** Where an issued magic link goes. The server logs a notice; the CLI prints the URL. */
export interface AuthLayerOptions {
  readonly onMagicLink: (link: {
    readonly email: string;
    readonly url: string;
  }) => Effect.Effect<void>;
}

/** Better Auth answers session lookups from Postgres; anything slower than this is a fault. */
export const SESSION_TIMEOUT = "5 seconds";
/** Upper bound for one auth request (WebAuthn ceremonies included). */
export const HANDLE_TIMEOUT = "30 seconds";
/** How long shutdown waits for the pg pool to drain before abandoning it (a dead database must not block exit). */
export const POOL_CLOSE_TIMEOUT = "5 seconds";

/** Where the web app lands after a magic link signs the owner in (ADR 0003). */
export const MAGIC_LINK_CALLBACK_PATH = "/passkeys";
/** Where a failed magic link lands; the page reads `?error=<code>`. */
export const MAGIC_LINK_ERROR_PATH = "/login";

const timedOut = (operation: AuthError["operation"], duration: string) =>
  Effect.fail(new AuthError({ operation, cause: new Error(`${operation} exceeded ${duration}`) }));

export class Auth extends Context.Service<Auth, AuthShape>()("bloom/server/Auth") {
  /** Builds the service with a caller-supplied magic-link sink. */
  static readonly make = Effect.fn("Auth.make")(function* (options: AuthLayerOptions) {
    const config = yield* ServerConfig;
    const pool = yield* Effect.acquireRelease(
      Effect.sync(() => new Pool({ connectionString: Redacted.value(config.databaseUrl) })),
      (pool) =>
        Effect.promise(() => pool.end()).pipe(
          Effect.timeoutOrElse({
            duration: POOL_CLOSE_TIMEOUT,
            orElse: () => Effect.logWarning("auth: closing the pg pool timed out; abandoning it"),
          }),
          Effect.catchCause(() => Effect.logWarning("auth: closing the pg pool failed")),
        ),
    );
    const context = yield* Effect.context<never>();
    const auth = createAuth({
      database: pool,
      secret: Redacted.value(config.betterAuthSecret),
      webOrigin: config.webOrigin,
      rpId: config.passkeyRpId,
      rpName: config.passkeyRpName,
      onMagicLink: (link) => Effect.runPromiseWith(context)(options.onMagicLink(link)),
    });

    const handle = Effect.fn("Auth.handle")(function* (request: Request) {
      return yield* Effect.tryPromise({
        try: () => auth.handler(request),
        catch: (cause) => new AuthError({ operation: "handle", cause }),
      }).pipe(
        Effect.timeoutOrElse({
          duration: HANDLE_TIMEOUT,
          orElse: () => timedOut("handle", HANDLE_TIMEOUT),
        }),
      );
    });

    const getSession = Effect.fn("Auth.getSession")(function* (headers: Headers) {
      const result = yield* Effect.tryPromise({
        try: () => auth.api.getSession({ headers }),
        catch: (cause) => new AuthError({ operation: "getSession", cause }),
      }).pipe(
        Effect.timeoutOrElse({
          duration: SESSION_TIMEOUT,
          orElse: () => timedOut("getSession", SESSION_TIMEOUT),
        }),
      );
      return result === null
        ? Option.none()
        : Option.some({
            user: { id: result.user.id, email: result.user.email, name: result.user.name },
          });
    });

    const requestMagicLink = Effect.fn("Auth.requestMagicLink")(function* (email: string) {
      yield* Effect.tryPromise({
        try: () =>
          auth.api.signInMagicLink({
            body: {
              email,
              callbackURL: MAGIC_LINK_CALLBACK_PATH,
              errorCallbackURL: MAGIC_LINK_ERROR_PATH,
            },
            headers: new Headers({ origin: config.webOrigin }),
          }),
        catch: (cause) => new AuthError({ operation: "requestMagicLink", cause }),
      }).pipe(
        Effect.timeoutOrElse({
          duration: HANDLE_TIMEOUT,
          orElse: () => timedOut("requestMagicLink", HANDLE_TIMEOUT),
        }),
      );
    });

    return Auth.of({ handle, getSession, requestMagicLink });
  });

  /** `Auth` with a custom magic-link sink (the CLI prints the URL). */
  static readonly layerWith = (options: AuthLayerOptions) => Layer.effect(Auth, Auth.make(options));

  /**
   * The server's `Auth`. A magic link requested through the HTTP API is never
   * delivered: the only issuer is `bun run auth:link` (ADR 0003), so the server
   * logs a notice without the address or the URL.
   */
  static readonly layer = Auth.layerWith({
    onMagicLink: () =>
      Effect.logInfo("magic link requested; links are only issued by bun run auth:link"),
  });
}
/**
 * Mounts Better Auth under `/api/auth/*` on the raw `HttpRouter`. Requests are
 * handed over as Web `Request`s (the Bun server already has one, so bodies
 * stream through untouched) and the Web `Response` is converted back.
 */
import { Effect } from "effect";
import { HttpRouter, HttpServerRequest, HttpServerResponse } from "effect/http";
import { AUTH_BASE_PATH } from "./auth.ts";
import { Auth } from "./service.ts";

export const AUTH_ROUTE_PATTERN = `${AUTH_BASE_PATH}/*` as const;

export const AuthRoutes = HttpRouter.use(
  Effect.fn("AuthRoutes")(function* (router) {
    const auth = yield* Auth;
    yield* router.add("*", AUTH_ROUTE_PATTERN, (request) =>
      HttpServerRequest.toWeb(request).pipe(
        Effect.flatMap(auth.handle),
        Effect.map(HttpServerResponse.fromWeb),
        Effect.catch((error) =>
          Effect.logError("auth request failed").pipe(
            Effect.annotateLogs({ "bloom.auth.error": error._tag }),
            Effect.as(HttpServerResponse.empty({ status: 500 })),
          ),
        ),
        Effect.withSpan("auth.handle"),
      ),
    );
  }),
);
/**
 * Entry point for the Better Auth CLI only (schema generation):
 *
 *   bunx auth@1.7.7 generate --config apps/server/src/auth/better-auth.cli.ts -y
 *
 * The generated DDL is not consumed from disk: it is inlined verbatim in the
 * `@bloom/db` migration `0001_better_auth` (ADR 0012), so the `--output` path
 * does not matter. Re-run the generator after upgrading Better Auth or adding
 * a plugin, diff the output against that migration, and add a new migration
 * for any change.
 *
 * Never import this from application code; the server builds its instance in
 * a Layer (`src/auth/service.ts`). Values here are placeholders: `generate`
 * never opens a connection, so the pool is created lazily and never used.
 */
import { Pool } from "pg";
import { createAuth } from "./auth.ts";

export const auth = createAuth({
  database: new Pool({
    connectionString:
      process.env["DATABASE_URL"] ?? "REDACTED",
  }),
  secret: process.env["BETTER_AUTH_SECRET"] ?? "schema-generation-only-not-a-real-secret-value",
  webOrigin: process.env["BLOOM_WEB_ORIGIN"] ?? "http://localhost:5173",
  rpId: process.env["BLOOM_PASSKEY_RP_ID"] ?? "localhost",
  rpName: process.env["BLOOM_PASSKEY_RP_NAME"] ?? "Bloom",
  onMagicLink: async () => {},
});
/**
 * `bun run auth:link`: prints a magic link for the owner (ADR 0003). The link
 * signs the owner in and lands on `/passkeys`; failures land on
 * `/login?error=<code>`. The URL is the only line written to stdout, so it
 * can be piped. Run from the repo root so Bun loads `.env`.
 */
import { BunRuntime } from "@effect/platform-bun";
import { Console, Effect, Layer, Logger, References } from "effect";
import { Auth } from "../auth/service.ts";
import { ServerConfig } from "../config.ts";

const program = Effect.gen(function* () {
  const config = yield* ServerConfig;
  const auth = yield* Auth;
  yield* auth.requestMagicLink(config.ownerEmail);
});

const AuthCli = Auth.layerWith({
  onMagicLink: ({ url }) => Console.log(url),
});

/** Only warnings and errors reach the terminal, so stdout stays the URL alone. */
const Quiet = Layer.mergeAll(
  Logger.layer([Logger.consolePretty({ mode: "tty" })]),
  Layer.succeed(References.MinimumLogLevel, "Warn"),
);

const CliLive = AuthCli.pipe(Layer.provideMerge(ServerConfig.layer), Layer.provideMerge(Quiet));

if (import.meta.main) {
  BunRuntime.runMain(program.pipe(Effect.scoped, Effect.provide(CliLive)));
}

