/**
 * Server configuration, read once from the environment with Effect `Config`.
 *
 * Bun loads `.env` from the current working directory, so every entry point
 * (`bun run dev:server`, `bun run auth:link`, `bun test apps/server`) must be
 * launched from the repo root. Secrets are `Redacted` so they never print.
 */
import {
  Config,
  Context,
  Effect,
  Layer,
  type LogLevel,
  Option,
  type Redacted,
  Schema,
} from "effect";

export interface ServerConfigShape {
  /** TCP port the HTTP server binds (`PORT`, default 3000; 0 lets the OS pick, for tests). */
  readonly port: number;
  /** Browser origin of the web app (`BLOOM_WEB_ORIGIN`); cookies and passkeys bind to it (ADR 0004). */
  readonly webOrigin: string;
  /** `DATABASE_URL`, shared by `@bloom/db`, Better Auth and pg-boss. */
  readonly databaseUrl: Redacted.Redacted;
  /** `BETTER_AUTH_SECRET`: signs cookies and hashes tokens. */
  readonly betterAuthSecret: Redacted.Redacted;
  /** WebAuthn relying party (`BLOOM_PASSKEY_RP_ID`, `BLOOM_PASSKEY_RP_NAME`). */
  readonly passkeyRpId: string;
  readonly passkeyRpName: string;
  /** The single owner's email (`BLOOM_OWNER_EMAIL`); the CLI issues magic links for it. */
  readonly ownerEmail: string;
  /** OTLP/HTTP base URL of the collector (`OTEL_EXPORTER_OTLP_ENDPOINT`); none disables export. */
  readonly otlpEndpoint: Option.Option<string>;
  /** `OTEL_SERVICE_NAME`, default `bloom-server`. */
  readonly serviceName: string;
  /** Directory of the static SvelteKit build served in production (`BLOOM_WEB_DIST`). */
  readonly webDist: string;
  /** Minimum log level (`LOG_LEVEL`, default `Info`). */
  readonly logLevel: LogLevel.LogLevel;
  /** Owner's IANA time zone (`BLOOM_TIME_ZONE`), consumed by the interruption policy. */
  readonly timeZone: Option.Option<string>;
}

/** The raw `Config` description; `ServerConfig.layer` is the usual way to consume it. */
export const serverConfig: Config.Config<ServerConfigShape> = Config.all({
  port: Config.schema(
    Schema.Int.check(Schema.isBetween({ minimum: 0, maximum: 65535 })),
    "PORT",
  ).pipe(Config.withDefault(3000)),
  webOrigin: Config.NonEmptyString("BLOOM_WEB_ORIGIN"),
  databaseUrl: Config.Redacted("DATABASE_URL"),
  betterAuthSecret: Config.Redacted("BETTER_AUTH_SECRET"),
  passkeyRpId: Config.NonEmptyString("BLOOM_PASSKEY_RP_ID").pipe(Config.withDefault("localhost")),
  passkeyRpName: Config.NonEmptyString("BLOOM_PASSKEY_RP_NAME").pipe(Config.withDefault("Bloom")),
  ownerEmail: Config.NonEmptyString("BLOOM_OWNER_EMAIL").pipe(
    Config.map((email) => email.toLowerCase()),
  ),
  otlpEndpoint: Config.option(Config.NonEmptyString("OTEL_EXPORTER_OTLP_ENDPOINT")),
  serviceName: Config.NonEmptyString("OTEL_SERVICE_NAME").pipe(Config.withDefault("bloom-server")),
  webDist: Config.NonEmptyString("BLOOM_WEB_DIST").pipe(Config.withDefault("apps/web/build")),
  logLevel: Config.LogLevel("LOG_LEVEL").pipe(Config.withDefault<LogLevel.LogLevel>("Info")),
  timeZone: Config.option(Config.NonEmptyString("BLOOM_TIME_ZONE")),
});

/** Resolved configuration as a service, built once at startup. Fails the layer if a required variable is missing. */
export class ServerConfig extends Context.Service<ServerConfig, ServerConfigShape>()(
  "bloom/server/ServerConfig",
) {
  static readonly layer = Layer.effect(
    ServerConfig,
    Effect.gen(function* () {
      const config = yield* serverConfig;
      yield* Effect.logDebug("server config loaded").pipe(
        Effect.annotateLogs({
          "bloom.port": config.port,
          "bloom.web_origin": config.webOrigin,
          "bloom.otlp": Option.isSome(config.otlpEndpoint),
          "bloom.log_level": config.logLevel,
        }),
      );
      return ServerConfig.of(config);
    }),
  );
}
/**
 * `BloomApi` served by `HttpApiBuilder`: every group's handlers plus the
 * `Authorization` implementation, with the OpenAPI document and Scalar docs
 * under `/api` so a single origin serves everything (ADR 0004).
 */
import { BloomApi } from "@bloom/api";
import { Layer } from "effect";
import { HttpApiBuilder, HttpApiScalar } from "effect/http-api";
import { AuthorizationLive } from "../auth/authorization.ts";
import { HealthLive } from "./groups/health.ts";
import { MeLive } from "./groups/me.ts";
import { MessagesLive } from "./groups/messages.ts";
import { TasksLive } from "./groups/tasks.ts";
import { ThreadsLive } from "./groups/threads.ts";

export const OPENAPI_PATH = "/api/openapi.json";
export const DOCS_PATH = "/api/docs";

/** All five groups; `Authorization` is merged in because the HTTP pipeline resolves it when the routes are built. */
export const GroupsLive = Layer.mergeAll(
  HealthLive,
  MeLive,
  ThreadsLive,
  MessagesLive,
  TasksLive,
).pipe(Layer.provideMerge(AuthorizationLive));

/** The API routes plus `GET /api/openapi.json`. */
export const ApiRoutes = HttpApiBuilder.layer(BloomApi, { openapiPath: OPENAPI_PATH }).pipe(
  Layer.provide(GroupsLive),
);

/** Scalar API reference at `GET /api/docs`. */
export const DocsRoute = HttpApiScalar.layer(BloomApi, { path: DOCS_PATH });
import { BloomApi } from "@bloom/api";
import { DateTime, Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/** `GET /api/health`: public liveness; the only route without `Authorization`. */
export const HealthLive = HttpApiBuilder.group(BloomApi, "health", (handlers) =>
  handlers.handle("check", () =>
    Effect.map(DateTime.now, (time) => ({
      status: "ok" as const,
      service: "bloom-server" as const,
      time,
    })),
  ),
);
import { BloomApi, CurrentUser } from "@bloom/api";
import { HttpApiBuilder } from "effect/http-api";

/** `GET /api/me`: echoes the `CurrentUser` the `Authorization` middleware resolved. */
export const MeLive = HttpApiBuilder.group(BloomApi, "me", (handlers) =>
  handlers.handle("get", () => CurrentUser),
);
import { AgentRunner, USER_FACING_MODEL_ERROR } from "@bloom/agent";
import { BloomApi } from "@bloom/api";
import { type ChatStreamEvent, ThreadService } from "@bloom/domain";
import { Effect, Stream } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/**
 * Turns the runner's stream into what the SSE contract allows (no failures).
 *
 * `AgentRunner.run` emits an `error` event and then fails with `ModelError`
 * (ADR 0013); the failure is dropped so the response ends cleanly after that
 * event. A `ThreadNotFound` inside the stream can only mean the thread vanished
 * between the handler's check and the run, so it becomes a terminal `error` event.
 */
const threadVanished: ChatStreamEvent = { type: "error", message: USER_FACING_MODEL_ERROR };

export const toSseStream = <R>(
  stream: Stream.Stream<
    ChatStreamEvent,
    { readonly _tag: "ModelError" } | { readonly _tag: "ThreadNotFound" },
    R
  >,
): Stream.Stream<ChatStreamEvent, never, R> =>
  stream.pipe(
    Stream.catchTags({
      ModelError: () => Stream.empty,
      ThreadNotFound: () => Stream.succeed(threadVanished),
    }),
  );

/**
 * `POST /api/threads/:id/messages`. The runner persists the user turn itself,
 * so the handler only verifies the thread (an unknown id is a 404 before any
 * bytes are streamed) and hands the run over as SSE.
 */
export const MessagesLive = HttpApiBuilder.group(
  BloomApi,
  "messages",
  Effect.fn(function* (handlers) {
    const threads = yield* ThreadService;
    const runner = yield* AgentRunner;
    return handlers.handle(
      "send",
      Effect.fn(function* ({ params, payload }) {
        yield* threads.get(params.id);
        return toSseStream(runner.run({ threadId: params.id, text: payload.text }));
      }),
    );
  }),
);
import { BloomApi, decodePayload } from "@bloom/api";
import { Task, TaskService } from "@bloom/domain";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/** `POST /api/tasks` carries the encoded side of `Task.jsonCreate` (ADR 0014). */
const decodeTaskCreate = decodePayload(Task.jsonCreate);

/** Every mutation goes through `TaskService` as the `user` actor, so the audit `Event` is written. */
export const TasksLive = HttpApiBuilder.group(
  BloomApi,
  "tasks",
  Effect.fn(function* (handlers) {
    const tasks = yield* TaskService;
    return handlers.handleAll({
      list: ({ query }) =>
        tasks.list(query.status === undefined ? undefined : { status: query.status }),
      create: ({ payload }) =>
        Effect.flatMap(decodeTaskCreate(payload), (input) => tasks.create(input, "user")),
      get: ({ params }) => tasks.get(params.id),
      update: ({ params, payload }) => tasks.update(params.id, payload, "user"),
      complete: ({ params }) => tasks.complete(params.id, "user"),
      remove: ({ params }) => tasks.remove(params.id, "user"),
    });
  }),
);
import { BloomApi, decodePayload } from "@bloom/api";
import { MessageService, Thread, ThreadService } from "@bloom/domain";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/http-api";

/**
 * `POST /api/threads` carries the encoded side of `Thread.jsonCreate` with
 * `kind` narrowed to `side | quest` (ADR 0014); decoding applies the defaults.
 */
const decodeThreadCreate = decodePayload(Thread.jsonCreate);

/** Threads group: list/create/get/main plus the message history of a thread. */
export const ThreadsLive = HttpApiBuilder.group(
  BloomApi,
  "threads",
  Effect.fn(function* (handlers) {
    const threads = yield* ThreadService;
    const messages = yield* MessageService;
    return handlers.handleAll({
      list: () => threads.list,
      create: ({ payload }) => Effect.flatMap(decodeThreadCreate(payload), threads.create),
      main: () => threads.ensureMain,
      get: ({ params }) => threads.get(params.id),
      messages: ({ params, query }) =>
        threads
          .get(params.id)
