/* Bloom visual baseline. Calm, earthy, quiet. This is a skeleton, not a brand launch. */

:root {
  color-scheme: light dark;

  /* Palette */
  --color-page: #f5efe4;
  --color-surface: #fbf7ef;
  --color-surface-muted: #efe7d8;
  --color-ink: #2a2622;
  --color-ink-muted: #6b625a;
  --color-ink-faint: #9a8f84;
  --color-accent: #9f512e;
  --color-accent-ink: #fff8f2;
  --color-sage: #7a8b6f;
  --color-sage-soft: #dfe5d7;
  --color-border: #e3d9c6;
  --color-danger: #9c3f2f;

  --shadow-soft: 0 1px 2px rgb(42 38 34 / 0.05), 0 6px 20px rgb(42 38 34 / 0.06);
  --shadow-lift: 0 2px 4px rgb(42 38 34 / 0.06), 0 12px 32px rgb(42 38 34 / 0.1);

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;

  --radius: 12px;
  --radius-sm: 8px;
  --radius-pill: 999px;

  --content-max: 720px;
  --sidebar-width: 320px;

  --font-sans:
    ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;

  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.375rem;

  --leading: 1.6;
  --transition: 180ms ease;
}

@media (prefers-color-scheme: dark) {
  :root {
    --color-page: #1d1a17;
    --color-surface: #26221e;
    --color-surface-muted: #2f2a25;
    --color-ink: #efe7da;
    --color-ink-muted: #b3a89a;
    --color-ink-faint: #7f756a;
    --color-accent: #cf7c59;
    --color-accent-ink: #1d1a17;
    --color-sage: #93a487;
    --color-sage-soft: #333a2f;
    --color-border: #3a332c;
    --color-danger: #d9775f;

    --shadow-soft: 0 1px 2px rgb(0 0 0 / 0.3), 0 6px 20px rgb(0 0 0 / 0.25);
    --shadow-lift: 0 2px 4px rgb(0 0 0 / 0.35), 0 12px 32px rgb(0 0 0 / 0.35);
  }
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --transition: 0ms;
  }
}

