import { Capture } from "@bloom/domain";
import { Effect, Schema } from "effect";
import { SqlClient, SqlModel, SqlSchema } from "effect/sql";
import { jsonb } from "./jsonb.ts";

/** Internal repository over the `captures` table; `payload` is jsonb. */
export const makeCaptureRepo = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;
  const repo = yield* SqlModel.makeRepository(Capture, {
    tableName: "captures",
    spanPrefix: "CaptureRepo",
    idColumn: "id",
  });

  const insert = SqlSchema.findOne({
    Request: Capture.insert,
    Result: Capture,
    execute: (row) =>
      sql`INSERT INTO captures ${sql.insert({ ...row, payload: jsonb(row.payload) }).returning("*")}`,
  });

  const list = SqlSchema.findAll({
    Request: Schema.Void,
    Result: Capture,
    execute: () => sql`SELECT * FROM captures ORDER BY created_at, seq`,
  });

  return {
    findById: repo.findById,
    update: repo.update,
    delete: repo.delete,
    insert,
    list,
  } as const;
});
import { Event } from "@bloom/domain";
import { Effect, Schema } from "effect";
import { SqlClient, SqlModel, SqlSchema } from "effect/sql";
import { jsonb } from "./jsonb.ts";

/**
 * Internal repository over the append-only `events` table. `payload` is jsonb
 * and bound as JSON text. `insertIfNew` relies on the partial unique
 * index on `dedupe_key` so duplicates are detected atomically.
 */
export const makeEventRepo = Effect.gen(function* () {
  const sql = yield* SqlClient.SqlClient;
  const repo = yield* SqlModel.makeRepository(Event, {
    tableName: "events",
    spanPrefix: "EventRepo",
    idColumn: "id",
  });

  /** Zero rows back means another event already carries this dedupe_key. */
  const insertIfNew = SqlSchema.findAll({
    Request: Event.insert,
    Result: Event,
    execute: (row) =>
      sql`INSERT INTO events ${sql.insert({ ...row, payload: jsonb(row.payload) })}
          ON CONFLICT (dedupe_key) WHERE dedupe_key IS NOT NULL DO NOTHING RETURNING *`,
  });

  const list = SqlSchema.findAll({
    Request: Schema.Void,
    Result: Event,
    execute: () => sql`SELECT * FROM events ORDER BY created_at, seq`,
  });

  return { findById: repo.findById, insertIfNew, list } as const;
});
import { Event, type EventIngest, EventSink, type IngestResult } from "@bloom/domain";
import { Effect, Layer } from "effect";
import { SqlClient } from "effect/sql";
import { makeEventRepo } from "../repos/events.ts";

/**
 * Inserts an event, or reports a duplicate when `dedupeKey` was seen before.
 * Shared by `EventSinkDb` and by `TaskServiceDb` (audit events in the same
 * transaction), so neither layer depends on the other.
 */
export const makeIngest = (repo: Effect.Success<typeof makeEventRepo>) =>
  Effect.fn("EventSink.ingest")(function* (input: EventIngest) {
    const dedupeKey = input.dedupeKey ?? null;
    const row = yield* Event.insert.makeEffect({
      source: input.source,
      type: input.type,
      occurredAt: input.occurredAt,
      payload: input.payload,
      dedupeKey,
    });
    const inserted = yield* repo.insertIfNew(row);
    const event = inserted[0];
    if (event === undefined) {
      // Only a dedupe_key conflict yields zero rows; without a key the insert cannot be skipped.
      return { _tag: "Duplicate", dedupeKey: dedupeKey ?? "" } satisfies IngestResult;
    }
    return { _tag: "Inserted", event } satisfies IngestResult;
  }, Effect.orDie);

/** Postgres-backed `EventSink`. Duplicate detection is a single INSERT ... ON CONFLICT DO NOTHING. */
export const EventSinkDb: Layer.Layer<EventSink, never, SqlClient.SqlClient> = Layer.effect(
  EventSink,
  Effect.gen(function* () {
    const repo = yield* makeEventRepo;
    return EventSink.of({ ingest: makeIngest(repo) });
  }),
);
