/**
 * Test-only handlers for `BloomApi`. They exercise the contract against the
 * domain `layerMemory` layers; the real handlers live in `apps/server`.
 */
import {
  type ChatStreamEvent,
  MessageService,
  Task,
  TaskService,
  Thread,
  ThreadService,
  UserId,
} from "@bloom/domain";
import { DateTime, Effect, Layer, Schema, Stream } from "effect";
import { HttpApiBuilder } from "effect/http-api";
import { BloomApi } from "../src/api.ts";
import { Authorization, type AuthUser, CurrentUser, Unauthorized } from "../src/auth.ts";
import { decodePayload } from "../src/payload.ts";

const decodeTaskCreate = decodePayload(Task.jsonCreate);
const decodeThreadCreate = decodePayload(Thread.jsonCreate);

/** The single owner every allowed request runs as. */
export const fixedUser: AuthUser = {
  id: Schema.decodeSync(UserId)("user-gabby"),
  email: "gabby@example.com",
  name: "Gabby",
};

/** Authorization that accepts every request and provides `fixedUser`. */
export const AuthorizationAllow = Layer.succeed(Authorization)((httpEffect) =>
  Effect.provideService(httpEffect, CurrentUser, fixedUser),
);

/** Authorization that rejects every request with `Unauthorized`. */
export const AuthorizationReject = Layer.succeed(Authorization)(() =>
  Effect.fail(new Unauthorized({ message: "No session cookie" })),
);

export const HealthHandlers = HttpApiBuilder.group(BloomApi, "health", (handlers) =>
  handlers.handle("check", () =>
    Effect.map(DateTime.now, (time) => ({
      status: "ok" as const,
      service: "bloom-server" as const,
      time,
    })),
  ),
);

export const MeHandlers = HttpApiBuilder.group(BloomApi, "me", (handlers) =>
  handlers.handle("get", () => CurrentUser),
);

export const ThreadsHandlers = HttpApiBuilder.group(
  BloomApi,
  "threads",
  Effect.fn(function* (handlers) {
    const threads = yield* ThreadService;
    const messages = yield* MessageService;
    return handlers.handleAll({
      list: () => threads.list,
      create: ({ payload }) => Effect.flatMap(decodeThreadCreate(payload), threads.create),
      main: () => threads.ensureMain,
      get: ({ params }) => threads.get(params.id),
      messages: ({ params, query }) =>
        threads
          .get(params.id)
          .pipe(
            Effect.flatMap(() =>
              messages.list(params.id, query.limit === undefined ? {} : { limit: query.limit }),
            ),
          ),
    });
  }),
);

/**
 * Stand-in for the agent: records the user turn, writes an echo reply and
 * streams three events for it.
 */
export const MessagesHandlers = HttpApiBuilder.group(
  BloomApi,
  "messages",
  Effect.fn(function* (handlers) {
    const threads = yield* ThreadService;
    const messages = yield* MessageService;
    return handlers.handle(
      "send",
      Effect.fn(function* ({ params, payload }) {
        yield* threads.get(params.id);
        yield* messages.append({
          threadId: params.id,
          role: "user",
          parts: [{ type: "text", text: payload.text }],
        });
        const replyText = `echo: ${payload.text}`;
        const reply = yield* messages.append({
          threadId: params.id,
          role: "assistant",
          parts: [{ type: "text", text: replyText }],
        });
        const events: ReadonlyArray<ChatStreamEvent> = [
          { type: "message_start", messageId: reply.id, threadId: params.id },
          { type: "text_delta", messageId: reply.id, delta: replyText },
          { type: "message_end", message: reply },
        ];
        return Stream.make(...events);
      }),
    );
  }),
);

export const TasksHandlers = HttpApiBuilder.group(
  BloomApi,
  "tasks",
  Effect.fn(function* (handlers) {
    const tasks = yield* TaskService;
    return handlers.handleAll({
      list: ({ query }) =>
        tasks.list(query.status === undefined ? undefined : { status: query.status }),
      create: ({ payload }) =>
        Effect.flatMap(decodeTaskCreate(payload), (input) => tasks.create(input, "user")),
      get: ({ params }) => tasks.get(params.id),
      update: ({ params, payload }) => tasks.update(params.id, payload, "user"),
      complete: ({ params }) => tasks.complete(params.id, "user"),
      remove: ({ params }) => tasks.remove(params.id, "user"),
    });
  }),
);

/** Every group's test handlers over fresh in-memory domain services. */
export const TestHandlers = Layer.mergeAll(
  HealthHandlers,
  MeHandlers,
  ThreadsHandlers,
  MessagesHandlers,
  TasksHandlers,
).pipe(
  Layer.provide(
    Layer.mergeAll(TaskService.layerMemory, ThreadService.layerMemory, MessageService.layerMemory),
  ),
);
import { describe, expect, it } from "bun:test";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { openApiSpec, renderOpenApiJson } from "../src/openapi.ts";

const packageDir = fileURLToPath(new URL("..", import.meta.url));

describe("OpenAPI", () => {
  const spec = openApiSpec();

  it("carries the API metadata", () => {
    expect(spec.openapi).toBe("3.1.0");
    expect(spec.info.title).toBe("Bloom API");
    expect(spec.info.version).toBe("0.1.0");
  });

  it("puts every path under /api and none under /api/auth", () => {
    const paths = Object.keys(spec.paths);
    expect(paths.length).toBeGreaterThan(0);
    for (const path of paths) {
      expect(path.startsWith("/api/")).toBe(true);
      expect(path.startsWith("/api/auth")).toBe(false);
      expect(path.endsWith("/")).toBe(false);
    }
  });

  it("includes the expected paths and methods", () => {
    expect(spec.paths["/api/health"]?.get).toBeDefined();
    expect(spec.paths["/api/me"]?.get).toBeDefined();
    expect(spec.paths["/api/tasks"]?.get).toBeDefined();
    expect(spec.paths["/api/tasks"]?.post).toBeDefined();
    expect(spec.paths["/api/tasks/{id}"]?.get).toBeDefined();
    expect(spec.paths["/api/tasks/{id}"]?.patch).toBeDefined();
    expect(spec.paths["/api/tasks/{id}"]?.delete).toBeDefined();
    expect(spec.paths["/api/tasks/{id}/complete"]?.post).toBeDefined();
    expect(spec.paths["/api/threads"]?.get).toBeDefined();
    expect(spec.paths["/api/threads"]?.post).toBeDefined();
    expect(spec.paths["/api/threads/main"]?.get).toBeDefined();
    expect(spec.paths["/api/threads/{id}"]?.get).toBeDefined();
    expect(spec.paths["/api/threads/{id}/messages"]?.get).toBeDefined();
    expect(spec.paths["/api/threads/{id}/messages"]?.post).toBeDefined();
  });

  it("keeps create payloads minimal: only title / kind are required, and kind excludes main", () => {
    const task = spec.paths["/api/tasks"]?.post?.requestBody?.content["application/json"]?.schema;
    expect(task?.required).toEqual(["title"]);
    const thread =
      spec.paths["/api/threads"]?.post?.requestBody?.content["application/json"]?.schema;
    expect(thread).toMatchObject({
      required: ["kind"],
      properties: { kind: { enum: ["side", "quest"] } },
    });
  });

  it("describes the chat stream as text/event-stream", () => {
    const content = spec.paths["/api/threads/{id}/messages"]?.post?.responses[200]?.content;
    expect(content).toBeDefined();
    expect(Object.keys(content ?? {})).toEqual(["text/event-stream"]);
  });

  it("documents 404 and 401 responses on protected endpoints", () => {
    const responses = spec.paths["/api/tasks/{id}"]?.get?.responses ?? {};
    expect(Object.keys(responses)).toContain("404");
    expect(Object.keys(responses)).toContain("401");
    expect(Object.keys(spec.paths["/api/health"]?.get?.responses ?? {})).not.toContain("401");
    expect(Object.keys(spec.paths["/api/tasks/{id}"]?.delete?.responses ?? {})).toContain("204");
  });

  it("renders pretty JSON with a trailing newline", () => {
    const json = renderOpenApiJson();
    expect(json.endsWith("}\n")).toBe(true);
    expect(json.includes('\n  "openapi"')).toBe(true);
    expect(JSON.parse(json)).toEqual(spec);
  });

  it("emit-openapi writes the document and exits 0", () => {
    const dir = mkdtempSync(join(tmpdir(), "bloom-openapi-"));
    const target = join(dir, "openapi.json");
    try {
      const result = Bun.spawnSync(["bun", "run", "scripts/emit-openapi.ts", target], {
        cwd: packageDir,
        stdout: "pipe",
        stderr: "pipe",
      });
      expect(result.exitCode).toBe(0);
      const written = JSON.parse(readFileSync(target, "utf8")) as typeof spec;
      expect(Object.keys(written.paths)).toContain("/api/health");
      expect(Object.keys(written.paths)).toContain("/api/tasks/{id}");
      expect(Object.keys(written.paths)).toContain("/api/threads/{id}/messages");
      expect(readFileSync(target, "utf8").endsWith("\n")).toBe(true);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
